/// <summary>
/// SalesOrderLineCDSV2Entity COC class
/// </summary>
[ExtensionOf(tableStr(SalesOrderLineCDSV2Entity))]
final class METSalesOrderLineCDSV2Entity_Extension
{
    #OCCRetryCount

}

Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        SalesLine                       salesLine;
        SalesTable                      salesTable;
        METSalesTable                   metSalesTable;
        PurchLine                       purchLine;
        PurchTable                      purchTable;
        METPurchTable                   metPurchTable;
        InventTransOrigin               inventTransOriginSales;
        InventTransOrigin               inventTransOriginPurch;
        METSalesPurchLineShipDateTmp    purchLineShipDateTmp;
        SalesQty                        qtyRemain;
        METSalesOrderAutoReserve        metSalesOrderAutoReserve;
        SalesLine                       newSalesLine;

        boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderLineV2Entity, SalesLine))
        {
            salesLine   = _dataSourceCtx.getBuffer() as SalesLine;
            salesTable  = salesLine.salesTable();            
            
            if (salesLine.Reservation == ItemReservation::Automatic)
            {
                metSalesOrderAutoReserve    = new METSalesOrderAutoReserve();
                newSalesLine    = metSalesOrderAutoReserve.applySubstitution(salesLine, METSalesLine::find(salesLine.RecId), salesLine.inventDim());

                if (newSalesLine.RecId)
                {
                    salesLine   = newSalesLine;
                }
            }

            if (salesLine.Reservation == ItemReservation::None && 
                MetSalesOrderTypes::find(salesTable.METSalesOrderType).OrderReserve == NoYes::Yes)
            {
                metSalesTable   = METSalesTable::findByRefRecId(salesTable.RecId);
                qtyRemain   = salesLine.SalesQty;

                insert_recordset purchLineShipDateTmp (RefRecId, ShippingDate)
                select RecId, ConfirmedDlv from purchLine
                    where purchLine.ItemId == salesLine.ItemId
                        && purchLine.InventDimId == salesLine.InventDimId
                        && purchLine.ConfirmedDlv != dateNull()
                    exists join purchTable
                        where purchTable.PurchId == purchLine.PurchId
                        exists join metPurchTable
                            where metPurchTable.PurchTable == purchTable.RecId
                                && metPurchTable.EventID == metSalesTable.EventID;

                insert_recordset purchLineShipDateTmp (RefRecId, ShippingDate)
                select RecId, DeliveryDate from purchLine
                    where purchLine.ItemId == salesLine.ItemId
                        && purchLine.InventDimId == salesLine.InventDimId
                        && purchLine.ConfirmedDlv == dateNull()
                    exists join purchTable
                        where purchTable.PurchId == purchLine.PurchId
                        exists join metPurchTable
                            where metPurchTable.PurchTable == purchTable.RecId
                                && metPurchTable.EventID == metSalesTable.EventID;

                while select purchLine order by purchLineShipDateTmp.ShippingDate
                    where purchLine.ItemId == salesLine.ItemId
                        && purchLine.InventDimId == salesLine.InventDimId
                    join purchLineShipDateTmp
                        where purchLineShipDateTmp.RefRecId == purchLine.RecId
                    exists join purchTable
                        where purchTable.PurchId == purchLine.PurchId
                        exists join metPurchTable
                            where metPurchTable.PurchTable == purchTable.RecId
                                && metPurchTable.EventID == metSalesTable.EventID
                {
                    select firstonly RecId from inventTransOriginSales
                        where inventTransOriginSales.InventTransId == salesLine.InventTransId;

                    select firstonly RecId from inventTransOriginPurch
                        where inventTransOriginPurch.InventTransId == purchLine.InventTransId;

                    qtyRemain   -= InventTransOrigin::updateMarking(inventTransOriginSales.RecId, inventTransOriginPurch.RecId, -1 * qtyRemain);

                    if (qtyRemain > 0)
                    {
                        continue;
                    }
                    else
                    {
                        break;
                    }
                }
            }
        }     
    
        return ret;
    }

    /// <summary>
    /// Map data fields to virtual fields
    /// </summary>
    public void postLoad()
    {
        next postLoad();

        this.METReservedQuantity = SalesLine::findInventTransId(this.InventoryLotId).reservedPhysical();

    }
